/* Bộ câu hỏi IELTS Speaking bổ sung – đợt 2: Con người & Đời sống hằng ngày (tự biên soạn) */
(function (g) {
  g.SPEAK_MORE = (g.SPEAK_MORE || []).concat([
    {
      topic: 'society', title: 'Người lớn tuổi mà bạn ngưỡng mộ',
      p1: ["Who do you usually turn to when you need advice?", "Do you spend much time with older relatives?", "Did you have a favourite teacher when you were younger?", "In what ways are you similar to your parents?"],
      p2: { q: "Describe an older person you admire.", points: ["who this person is", "how you got to know them", "how they live their life or what they have achieved", "and explain why you look up to them"] },
      p3: ["What can young people learn from the older generation?", "Why do some teenagers choose celebrities as role models rather than family members?", "Is it harder for older people to adapt to change today than it was in the past?", "Should elderly people keep working if they are still healthy?"]
    },
    {
      topic: 'society', title: 'Giúp đỡ người khác',
      p1: ["Do you often help your friends with things?", "When was the last time someone helped you?", "Did your parents expect you to help around the house as a child?", "Is it easy for you to ask other people for help?"],
      p2: { q: "Describe an occasion when you gave someone a hand.", points: ["who you helped", "what the situation was", "what exactly you did", "and explain how you felt afterwards"] },
      p3: ["Why are some people more willing to help strangers than others?", "Do people in cities help each other less than people in the countryside?", "Should schools encourage children to volunteer in their community?", "Can technology make it easier for people to help one another?"]
    },
    {
      topic: 'education', title: 'Học kỹ năng qua mạng',
      p1: ["Have you ever watched a tutorial video to learn something?", "Which websites or apps do you use for studying?", "Do you prefer learning from a book or from a screen?", "Is there a skill you would like to learn online in the future?"],
      p2: { q: "Describe a skill you picked up through the internet.", points: ["what the skill is", "which website, app or channel you used", "how long it took you to learn it", "and explain how useful this skill has been for you"] },
      p3: ["What are the main advantages of online courses compared with classroom lessons?", "Why do so many people fail to finish the online courses they sign up for?", "Will online learning ever replace traditional schools?", "How can learners judge whether information they find online is reliable?"]
    },
    {
      topic: 'culture', title: 'Quà tặng',
      p1: ["Do you enjoy choosing presents for other people?", "On what occasions do people in your country give gifts?", "Have you ever received a present you did not like?", "Do you prefer giving handmade gifts or bought ones?"],
      p2: { q: "Describe a present you gave to someone that they really appreciated.", points: ["what the present was", "who you gave it to", "why you chose it", "and explain how the person reacted when they received it"] },
      p3: ["Do people spend too much money on gifts nowadays?", "Is it acceptable to give money instead of a present?", "How has online shopping changed the way people buy gifts?", "Why do companies sometimes give gifts to their clients?"]
    },
    {
      topic: 'health', title: 'Giấc ngủ & Nghỉ ngơi',
      p1: ["How many hours of sleep do you usually get?", "Do you ever take a nap during the day?", "What do you do to relax before going to bed?", "Do you find it easy to fall asleep in a new place?"],
      p2: { q: "Describe a time when you felt completely rested and refreshed.", points: ["when and where it was", "what you had been doing before that", "how you spent that time", "and explain why it made you feel so refreshed"] },
      p3: ["Why do so many people today not get enough sleep?", "Should employers allow staff to take short naps at work?", "How does a lack of sleep affect students' performance?", "Do you think people in the future will have more or less time to rest?"]
    },
    {
      topic: 'urban', title: 'Tiếng ồn',
      p1: ["Is the area where you live noisy or quiet?", "What kinds of noise annoy you the most?", "Do you prefer to study in silence or with some background sound?", "Have you ever complained about noise?"],
      p2: { q: "Describe a place you have been to that was extremely noisy.", points: ["where it was", "when you went there", "what was causing the noise", "and explain how you felt about being there"] },
      p3: ["Why are cities becoming noisier?", "How does noise pollution affect people's health?", "What can governments do to reduce noise in residential areas?", "Are young people more tolerant of noise than older people?"]
    },
    {
      topic: 'work', title: 'Đúng giờ & Quản lý thời gian',
      p1: ["Are you usually on time for appointments?", "How do you feel when other people are late?", "Do you use a planner or an app to organise your day?", "What time of day are you most productive?"],
      p2: { q: "Describe a time when you were late for something important.", points: ["what the event was", "why you were late", "what happened as a result", "and explain what you learned from the experience"] },
      p3: ["Is being punctual equally important in all cultures?", "Why do some people always seem to run out of time?", "Should children be taught time-management skills at school?", "Has modern technology helped us manage our time better, or has it made us busier?"]
    },
    {
      topic: 'urban', title: 'Hàng xóm & Láng giềng',
      p1: ["Do you know the people who live next door to you?", "How often do you talk to your neighbours?", "Have your neighbours ever helped you with anything?", "What makes someone a good neighbour?"],
      p2: { q: "Describe a neighbour who made a good impression on you.", points: ["who this neighbour was", "how long you lived near them", "what they did that you still remember", "and explain why you think they were a good neighbour"] },
      p3: ["Why do people in big cities often not know their neighbours?", "How can neighbours build a stronger sense of community?", "What kinds of problems commonly arise between neighbours?", "Is it important for children to grow up surrounded by a close-knit community?"]
    }
  ]);

  g.SPEAK_SAMPLES = Object.assign(g.SPEAK_SAMPLES || {}, {
    /* ===== Người lớn tuổi mà bạn ngưỡng mộ ===== */
    "Who do you usually turn to when you need advice?": { a: "Generally, I go to my older sister first. She's only four years older than me, but she's already been through a lot of the things I'm dealing with now, like choosing a university and finding a first job. She's honest without being harsh, so I always come away with a clearer head.", vocab: [["turn to someone", "tìm đến ai (để nhờ giúp, xin lời khuyên)"], ["go through", "trải qua"], ["come away with a clearer head", "ra về với đầu óc sáng suốt hơn"]] },
    "Do you spend much time with older relatives?": { a: "Not as much as I'd like, to be honest. My grandparents live in the countryside, about three hours away, so I usually only see them during holidays. When I do visit, though, I make a point of sitting with them and listening to their stories, because I know those moments won't last forever.", vocab: [["make a point of doing something", "cố ý làm điều gì, coi trọng việc làm điều gì"], ["to be honest", "thành thật mà nói"], ["won't last forever", "sẽ không kéo dài mãi"]] },
    "Did you have a favourite teacher when you were younger?": { a: "Yes, my primary school maths teacher. She had this gift for turning dull calculations into little puzzles and games, so even the kids who hated numbers ended up joining in. She was also incredibly patient, and I think that's partly why I never felt afraid of making mistakes in class.", vocab: [["have a gift for", "có năng khiếu, biệt tài về"], ["join in", "tham gia cùng"], ["incredibly patient", "cực kỳ kiên nhẫn"]] },
    "In what ways are you similar to your parents?": { a: "People say I've got my father's sense of humour, which is probably true because we laugh at exactly the same silly jokes. From my mum, I think I've inherited a tendency to plan everything in advance. I used to find that habit of hers a bit over the top, but now I catch myself doing exactly the same thing.", vocab: [["inherit a tendency", "thừa hưởng một thói quen, xu hướng"], ["over the top", "thái quá, quá mức"], ["catch myself doing something", "chợt nhận ra mình đang làm điều gì"]] },
    "Describe an older person you admire.": { a: "The person I'd like to talk about is Mr Hai, a retired engineer who lives a few doors down from my family's house. He's in his late seventies now.\n\nI got to know him about ten years ago, when I was struggling with physics at secondary school. My mum mentioned it to him in passing, and he offered to tutor me for free every Sunday morning.\n\nWhat strikes me most is the way he lives. Even after retiring, he never really slowed down. He taught himself to use a computer in his sixties, he still cycles to the market every day, and he runs a small reading corner for the children in our street, where he lends out his own books. He's also remarkably calm; I've never once heard him raise his voice.\n\nThe main reason I look up to him is that he shows ageing doesn't have to mean shrinking your world. Lots of people assume life gets smaller once you stop working, but he has made his bigger by staying curious and giving his time to others. Whenever I feel lazy or think I'm too old to start something new I remember him learning to type with two fingers at sixty-five. If I can be half as generous and open-minded as he is when I'm older, I'll be very happy.", vocab: [["mention something in passing", "nhắc đến điều gì một cách tình cờ, thoáng qua"], ["look up to someone", "ngưỡng mộ, kính trọng ai"], ["shrink your world", "thu hẹp thế giới của mình"]] },
    "What can young people learn from the older generation?": { a: "I'd say the most valuable thing is perspective. Older people have lived through hardships, like wars or economic crises, that most young people have only read about, so they tend to be better at telling a real problem from a minor setback. They can also pass on practical know-how, from cooking traditional dishes to managing money carefully. For instance, my grandmother taught me to save a little from every pay cheque, which is a habit I'm very grateful for now.", vocab: [["live through", "sống qua, trải qua (giai đoạn khó khăn)"], ["a minor setback", "một trở ngại nhỏ"], ["pass on practical know-how", "truyền lại kinh nghiệm thực tế"]] },
    "Why do some teenagers choose celebrities as role models rather than family members?": { a: "I think it's largely about visibility and glamour. Teenagers see celebrities on their phones every single day, looking successful and confident, so it's natural to want to imitate them. Parents, by comparison, seem ordinary because teenagers see them tired after work or worrying about bills. There's also the fact that adolescence is a time when young people want to define themselves as separate from their families, so admiring someone outside the home can be a way of asserting their independence.", vocab: [["visibility and glamour", "sự hiện diện thường xuyên và vẻ hào nhoáng"], ["imitate", "bắt chước"], ["assert their independence", "khẳng định sự độc lập của mình"]] },
    "Is it harder for older people to adapt to change today than it was in the past?": { a: "In many ways, yes, simply because the pace of change has accelerated so much. In the past, a technology might stay the same for decades, whereas now apps and devices are updated every few months. Many essential services, such as banking or booking a doctor's appointment, have moved online, so older people who aren't confident with smartphones can feel shut out. That said, a lot of elderly people are surprisingly adaptable when someone takes the time to show them patiently.", vocab: [["the pace of change", "tốc độ thay đổi"], ["feel shut out", "cảm thấy bị gạt ra ngoài"], ["surprisingly adaptable", "thích nghi tốt đến bất ngờ"]] },
    "Should elderly people keep working if they are still healthy?": { a: "I think it should be their choice rather than an obligation. For some people, work gives them a sense of purpose and keeps their minds sharp, so retiring abruptly can actually be bad for their wellbeing. Others have worked hard for forty years and deserve to rest and enjoy their grandchildren. Ideally, companies would offer flexible options, such as part-time roles or mentoring positions, so older employees can share their experience without the pressure of a full-time job.", vocab: [["a sense of purpose", "cảm giác có mục đích sống"], ["keep their minds sharp", "giữ cho đầu óc minh mẫn"], ["mentoring position", "vị trí cố vấn, kèm cặp"]] },

    /* ===== Giúp đỡ người khác ===== */
    "Do you often help your friends with things?": { a: "Yes, fairly often, although it's usually small stuff. I'm quite good with computers, so friends tend to call me whenever their laptop freezes or they need help setting something up. In return, they help me out with things I'm hopeless at, like cooking. I think that kind of give and take is what keeps a friendship healthy.", vocab: [["help someone out", "giúp ai một tay"], ["be hopeless at", "rất dở, hoàn toàn kém về"], ["give and take", "sự cho và nhận qua lại"]] },
    "When was the last time someone helped you?": { a: "Just last week, actually. I was carrying a huge box of books up to my fourth-floor flat and the lift was out of order. A guy from the floor below saw me struggling and offered to take the other end without me even asking. It only took five minutes, but it genuinely made my day.", vocab: [["out of order", "bị hỏng, không hoạt động"], ["struggle with something", "vật lộn, chật vật với việc gì"], ["make my day", "khiến cả ngày của tôi vui hẳn lên"]] },
    "Did your parents expect you to help around the house as a child?": { a: "Definitely. From about the age of seven, I had a few regular chores, like sweeping the floor and setting the table before dinner. I didn't always do them willingly, of course, but looking back, I'm glad my parents were strict about it. It meant that when I moved out for university, I already knew how to look after myself.", vocab: [["regular chores", "việc nhà thường ngày"], ["looking back", "nhìn lại (quá khứ)"], ["look after myself", "tự chăm sóc bản thân"]] },
    "Is it easy for you to ask other people for help?": { a: "Honestly, not really. I've always been quite independent, so I tend to try to sort things out on my own first, sometimes for far too long. I'm working on it, though, because I've realised that most people are actually happy to help, and asking early can save a lot of time and stress.", vocab: [["sort things out", "tự giải quyết mọi việc"], ["work on something", "cố gắng cải thiện điều gì"], ["save a lot of time and stress", "tiết kiệm nhiều thời gian và bớt căng thẳng"]] },
    "Describe an occasion when you gave someone a hand.": { a: "I'd like to talk about a time I helped an elderly tourist at a train station last summer.\n\nI was waiting for a train to visit my cousin when I noticed a Japanese woman, in her seventies, looking anxiously at the departure board. She was holding a printed ticket and kept asking staff for directions, but there seemed to be a language barrier, and they were too busy to give her much attention.\n\nI went over and asked, in English, whether she needed any help. It turned out her train had been moved to a different platform at the last minute and the announcement had only been made in Vietnamese. There were only about ten minutes left, so I carried her suitcase down the stairs, walked her across to the right platform and made sure she found her seat.\n\nAfterwards, I felt surprisingly emotional. She thanked me over and over and even tried to give me a little keychain from her bag, which I accepted because it seemed to mean a lot to her. What stayed with me was how easily she could have missed her train if nobody had stepped in. It reminded me that a few minutes of my time can make a huge difference to someone in an unfamiliar place, and I've tried to be more observant ever since.", vocab: [["a language barrier", "rào cản ngôn ngữ"], ["at the last minute", "vào phút chót"], ["step in", "can thiệp, ra tay giúp đỡ"]] },
    "Why are some people more willing to help strangers than others?": { a: "Upbringing plays a big part, I think. Children who grow up watching their parents help neighbours or volunteer tend to see helping as normal behaviour. Personality matters too: some people are naturally more empathetic, while others are shy or worry about getting involved in something awkward. There's also the bystander effect, where people in a crowd assume someone else will step in. So, ironically, a person alone on a quiet street might be more likely to help than someone in a busy square.", vocab: [["upbringing", "sự giáo dục, nuôi dạy từ nhỏ"], ["empathetic", "biết đồng cảm"], ["the bystander effect", "hiệu ứng người ngoài cuộc"]] },
    "Do people in cities help each other less than people in the countryside?": { a: "There's some truth in that stereotype, but I wouldn't exaggerate it. In rural villages, everyone knows everyone, so helping a neighbour is almost expected, and refusing could damage your reputation. In cities, people are busier and surrounded by strangers, so they tend to keep to themselves. However, city dwellers often help in different ways, for example by donating to charities or joining online fundraising campaigns, which can actually reach far more people than a single act of local kindness.", vocab: [["keep to themselves", "sống khép kín, ít giao tiếp"], ["city dwellers", "cư dân thành thị"], ["fundraising campaign", "chiến dịch gây quỹ"]] },
    "Should schools encourage children to volunteer in their community?": { a: "Yes, I strongly believe they should. Volunteering teaches things that are hard to learn from textbooks, like responsibility, teamwork and empathy for people from different backgrounds. For instance, a class that spends a morning cleaning a local park or reading to residents of a care home will understand their community far better afterwards. The key, though, is to keep it voluntary and enjoyable. If it becomes just another compulsory task to tick off, children may end up resenting it.", vocab: [["people from different backgrounds", "những người có hoàn cảnh khác nhau"], ["tick something off", "đánh dấu là đã xong (cho có)"], ["resent", "bực bội, không bằng lòng với"]] },
    "Can technology make it easier for people to help one another?": { a: "Absolutely. Crowdfunding platforms allow ordinary people to support someone's medical treatment on the other side of the country within hours. During floods in central Vietnam, for example, social media groups were used to coordinate rescue efforts and deliver supplies to exactly where they were needed. Apps also connect volunteers with local organisations. The only downside is that online appeals can occasionally be fraudulent, so people need to check that a cause is genuine before donating.", vocab: [["crowdfunding platform", "nền tảng gây quỹ cộng đồng"], ["coordinate rescue efforts", "điều phối công tác cứu hộ"], ["fraudulent", "gian lận, lừa đảo"]] },

    /* ===== Học kỹ năng qua mạng ===== */
    "Have you ever watched a tutorial video to learn something?": { a: "All the time! Just recently, I watched a short tutorial on how to replace the battery in my watch, which saved me a trip to the repair shop. I also use videos to pick up new recipes. What I like is that you can pause and rewind as many times as you need, which you can't really do with a human teacher.", vocab: [["save someone a trip", "giúp ai khỏi phải đi một chuyến"], ["pick up", "học được (một cách tự nhiên)"], ["pause and rewind", "tạm dừng và tua lại"]] },
    "Which websites or apps do you use for studying?": { a: "Mainly a flashcard app for vocabulary, because it reminds me to review words just before I'm likely to forget them. For more in-depth learning, I use free university lectures that are available online. I also listen to podcasts on my commute, which is a painless way to squeeze in some extra listening practice.", vocab: [["in-depth", "chuyên sâu"], ["commute", "quãng đường đi làm, đi học hằng ngày"], ["squeeze in", "tranh thủ chen vào (thời gian)"]] },
    "Do you prefer learning from a book or from a screen?": { a: "For serious study, I still prefer a printed book. I find I absorb information better when I can underline things and write notes in the margins, and there are no notifications popping up to distract me. That said, screens are unbeatable for quick reference or for subjects that need visuals, like learning a dance move.", vocab: [["absorb information", "tiếp thu thông tin"], ["in the margins", "ở lề trang sách"], ["unbeatable", "không gì sánh bằng"]] },
    "Is there a skill you would like to learn online in the future?": { a: "I'd really like to learn basic video editing. I take a lot of clips when I travel, but they just sit on my phone because I don't know how to turn them into something worth watching. There are loads of free beginner courses out there, so it's mostly a matter of finding the time.", vocab: [["basic video editing", "dựng, chỉnh sửa video cơ bản"], ["worth watching", "đáng xem"], ["a matter of", "chỉ là vấn đề (thời gian, ý chí…)"]] },
    "Describe a skill you picked up through the internet.": { a: "The skill I'd like to describe is touch typing, which means typing quickly without looking at the keyboard.\n\nI learned it about two years ago using a free typing website. The site gives you short exercises that focus on one group of letters at a time, and it tracks your speed and accuracy, so you can actually see yourself improving. Later on, I also watched a few videos on a channel run by a former office trainer, who explained how to sit properly and position your hands to avoid wrist pain.\n\nIt took me roughly six weeks of practising for around twenty minutes a day before I felt comfortable. The first fortnight was honestly frustrating, because I was slower than when I used two fingers, and I was really tempted to give up. But once the muscle memory kicked in, my speed jumped from about thirty words a minute to over sixty.\n\nThis skill has been far more useful than I expected. As a university student, I write a lot of assignments, and I can now take notes in lectures almost as fast as the lecturer speaks. It has also helped in my part-time job, where I answer customer emails. More importantly, it taught me that sticking with something through the awkward beginner stage really pays off, and that's a lesson I've applied to other things since.", vocab: [["touch typing", "đánh máy mười ngón không nhìn bàn phím"], ["muscle memory kicks in", "trí nhớ cơ bắp bắt đầu phát huy"], ["pay off", "mang lại kết quả xứng đáng"]] },
    "What are the main advantages of online courses compared with classroom lessons?": { a: "The biggest advantage is flexibility. Learners can study at their own pace and fit lessons around work or family commitments, which is ideal for adults. Online courses are also usually far cheaper, and they give people in remote areas access to teachers from top universities. Another benefit is that you can replay difficult parts as often as you need. For example, a nurse working night shifts could complete a qualification that would be impossible to attend in person.", vocab: [["at their own pace", "theo tốc độ của riêng mình"], ["family commitments", "trách nhiệm, bổn phận gia đình"], ["attend in person", "trực tiếp tham dự"]] },
    "Why do so many people fail to finish the online courses they sign up for?": { a: "I think the main reason is the lack of accountability. In a classroom, a teacher notices if you're absent and you don't want to fall behind your classmates, whereas online nobody is checking on you. Many courses are also free or very cheap, so people don't feel they're losing much by quitting. On top of that, learners often underestimate how much self-discipline it takes, and once daily life gets busy, the course is the first thing to go.", vocab: [["accountability", "trách nhiệm giải trình, sự bị giám sát"], ["fall behind", "bị tụt lại phía sau"], ["self-discipline", "tính kỷ luật tự giác"]] },
    "Will online learning ever replace traditional schools?": { a: "I doubt it, at least not completely. Schools do much more than deliver information; they teach children how to cooperate, resolve conflicts and build friendships, which really requires face-to-face contact. They also provide childcare so parents can work. What I can imagine is a blended model, where students cover some theory online at home and then use classroom time for discussion and practical projects. That would combine the strengths of both approaches.", vocab: [["face-to-face contact", "tiếp xúc trực tiếp"], ["a blended model", "mô hình học kết hợp (trực tuyến và trực tiếp)"], ["combine the strengths", "kết hợp những ưu điểm"]] },
    "How can learners judge whether information they find online is reliable?": { a: "A good first step is to check who is behind the content. Is it written by a recognised expert, a university or a reputable organisation, or by an anonymous account trying to sell something? Learners should also cross-check important facts with two or three independent sources. Another warning sign is when a post relies heavily on emotional language rather than evidence. Personally, I'm always suspicious of anything promising to make me fluent in a language in thirty days.", vocab: [["reputable", "có uy tín"], ["cross-check", "đối chiếu, kiểm tra chéo"], ["warning sign", "dấu hiệu cảnh báo"]] },

    /* ===== Quà tặng ===== */
    "Do you enjoy choosing presents for other people?": { a: "I do, but only when I have enough time. I like thinking about what someone actually needs or has mentioned wanting, rather than just grabbing something generic. The downside is that I can spend ages deciding, so last-minute gift shopping really stresses me out.", vocab: [["generic", "chung chung, không có nét riêng"], ["spend ages", "mất rất nhiều thời gian"], ["stress someone out", "khiến ai căng thẳng"]] },
    "On what occasions do people in your country give gifts?": { a: "The most important occasion is Lunar New Year, when people give lucky money in red envelopes, especially to children and elderly relatives. Apart from that, birthdays and weddings are big ones, and there are also special days like Teachers' Day in November, when students bring flowers or small gifts to show gratitude to their teachers.", vocab: [["lucky money", "tiền lì xì"], ["red envelope", "bao lì xì"], ["show gratitude", "bày tỏ lòng biết ơn"]] },
    "Have you ever received a present you did not like?": { a: "Yes, a few times. The one I remember best is a bright orange sweater from a distant aunt, which was about three sizes too big. Of course, I thanked her warmly because it's the thought that counts, but I have to admit it's been sitting at the back of my wardrobe ever since.", vocab: [["distant aunt", "dì, cô họ xa"], ["it's the thought that counts", "quan trọng là tấm lòng"], ["I have to admit", "tôi phải thừa nhận rằng"]] },
    "Do you prefer giving handmade gifts or bought ones?": { a: "It depends on the person. For close friends and family, I like making something personal, like a photo album or a handwritten card, because it shows I've invested time and effort. But for colleagues or people I don't know very well, a bought gift is safer and less awkward, especially if it's something practical they'll definitely use.", vocab: [["invest time and effort", "bỏ thời gian và công sức"], ["awkward", "ngượng ngùng, khó xử"], ["practical", "thiết thực"]] },
    "Describe a present you gave to someone that they really appreciated.": { a: "I'd like to talk about a present I gave my grandfather for his eightieth birthday last year: a printed book of his own life story.\n\nThe idea came about because he has always loved telling stories about his childhood, his time as a schoolteacher and how he met my grandmother. I realised that once he was gone, those stories would be lost, and the younger children in the family had never heard most of them.\n\nSo, over about three months, I visited him every weekend and recorded our conversations on my phone, pretending it was just a casual chat. Then I typed everything up, added old photographs I'd borrowed from relatives, and paid a local print shop to bind it into a proper hardback book.\n\nI chose it because he isn't a material person at all. What he values most is family, so I wanted to give him something that celebrated his life and connected him with his grandchildren.\n\nHis reaction is something I'll never forget. He went very quiet, turned the pages slowly and then took his glasses off to wipe his eyes. Later that evening, he read a few chapters aloud to everyone. He now keeps the book on his bedside table and proudly shows it to every visitor.", vocab: [["come about", "nảy ra, hình thành"], ["worth every penny", "đáng từng đồng"], ["a material person", "người coi trọng vật chất"]] },
    "Do people spend too much money on gifts nowadays?": { a: "In some cases, yes. Social media has created pressure to give impressive, photogenic presents, and some people feel they have to match what others spend, even if they can't really afford it. Weddings are a good example, as guests sometimes worry their cash gift will be judged. However, I'd say most people still spend sensibly. A thoughtful, inexpensive gift is often more memorable than an expensive one, and I think more people are starting to recognise that.", vocab: [["photogenic", "ăn ảnh, đẹp khi chụp"], ["can't afford", "không đủ khả năng chi trả"], ["spend sensibly", "chi tiêu hợp lý"]] },
    "Is it acceptable to give money instead of a present?": { a: "In my culture, it's completely acceptable and often preferred, particularly for weddings and Lunar New Year. Money is practical because the receiver can spend it on whatever they genuinely need, and nothing goes to waste. On the other hand, it can feel a bit impersonal for occasions like a close friend's birthday, where a gift shows that you've thought about their personality. So I'd say cash works well for formal occasions, while personal occasions deserve something more personal.", vocab: [["go to waste", "bị lãng phí"], ["impersonal", "thiếu tính cá nhân, xa cách"], ["formal occasion", "dịp trang trọng"]] },
    "How has online shopping changed the way people buy gifts?": { a: "It has made gift-giving far more convenient. You can compare thousands of options in minutes, read reviews and have the present delivered straight to someone in another city, often already wrapped. E-gift cards have also become popular for people who are short of time. The downside is that it has perhaps made gifts a little less personal, since you no longer spend an afternoon wandering round shops looking for that perfect item for someone special.", vocab: [["have something delivered", "cho giao (hàng) đến"], ["e-gift card", "thẻ quà tặng điện tử"], ["short of time", "thiếu thời gian"]] },
    "Why do companies sometimes give gifts to their clients?": { a: "Mainly to build long-term relationships. A well-chosen gift at New Year, for example, reminds clients that the company values their business, which makes them more likely to stay loyal rather than switch to a competitor. Gifts with the company logo also work as a subtle form of advertising. However, there's a fine line here, because very expensive gifts could look like bribery, so many firms now have strict rules about what is appropriate.", vocab: [["stay loyal", "giữ sự trung thành (với thương hiệu)"], ["a fine line", "ranh giới mong manh"], ["bribery", "sự hối lộ"]] },

    /* ===== Giấc ngủ & Nghỉ ngơi ===== */
    "How many hours of sleep do you usually get?": { a: "On weekdays, probably about six and a half hours, which I know isn't quite enough. I tend to stay up later than I should, scrolling on my phone or finishing assignments. At weekends I try to catch up by sleeping in, although I've read that doesn't really make up for the lost sleep.", vocab: [["stay up late", "thức khuya"], ["sleep in", "ngủ nướng, ngủ dậy muộn"], ["make up for", "bù đắp cho"]] },
    "Do you ever take a nap during the day?": { a: "Yes, a short one after lunch whenever I can. It's actually very common in Vietnam; many offices even turn the lights off for half an hour at midday. Twenty minutes is ideal for me. If I sleep much longer than that, I wake up feeling groggy and it takes ages to get going again.", vocab: [["take a nap", "chợp mắt, ngủ trưa"], ["groggy", "lờ đờ, uể oải"], ["get going", "bắt đầu hoạt động trở lại"]] },
    "What do you do to relax before going to bed?": { a: "I try to put my phone away about half an hour before bed, though I don't always manage it. Instead, I'll have a hot shower, make a cup of herbal tea and read a few pages of a novel. Reading something calm really helps me switch off, whereas checking the news just keeps my mind racing.", vocab: [["switch off", "thư giãn, gác lại mọi suy nghĩ"], ["herbal tea", "trà thảo mộc"], ["keep my mind racing", "khiến đầu óc cứ suy nghĩ liên tục"]] },
    "Do you find it easy to fall asleep in a new place?": { a: "Not at all, unfortunately. The first night in a hotel or a friend's house, I usually toss and turn for hours because of unfamiliar noises or a pillow that's too hard. I've started bringing an eye mask and earplugs when I travel, and they've made a noticeable difference.", vocab: [["toss and turn", "trằn trọc"], ["unfamiliar", "lạ lẫm, không quen"], ["make a noticeable difference", "tạo ra sự khác biệt rõ rệt"]] },
    "Describe a time when you felt completely rested and refreshed.": { a: "I'd like to talk about a weekend I spent at a small homestay in Da Lat, right after my final exams in my second year of university.\n\nThe month before had been exhausting. I'd been revising until two or three in the morning, surviving on instant noodles and coffee. As soon as my last exam finished, a friend and I booked a cheap bus ticket and headed for the mountains.\n\nThe homestay was a wooden house surrounded by pine trees, and there was no television and only a weak Wi-Fi signal, which turned out to be a blessing. We spent the two days doing very little. I slept for almost ten hours the first night, woke up to the sound of birds, and then we just went for long walks, drank hot soy milk at the local market and sat by a lake chatting.\n\nI think it made me feel so refreshed for a few reasons. First, the cool mountain air was a complete contrast to the heat and traffic of the city. Second, being almost offline meant my brain finally had a chance to slow down. When I got back, I felt like a different person, and it taught me that proper rest isn't laziness but something I need to plan for.", vocab: [["survive on", "sống tạm bợ nhờ (ăn uống qua loa)"], ["a blessing", "điều may mắn"], ["a complete contrast to", "hoàn toàn trái ngược với"]] },
    "Why do so many people today not get enough sleep?": { a: "There are several reasons, but screens are probably the biggest culprit. People take phones to bed and end up watching videos far later than they intended, and the blue light can make it harder to fall asleep. Work pressure is another factor; many employees answer emails late at night or work long hours to meet deadlines. In big cities, long commutes also eat into the evening. As a result, sleep is often the first thing people sacrifice when they're busy.", vocab: [["the biggest culprit", "thủ phạm chính, nguyên nhân lớn nhất"], ["eat into", "lấn vào, chiếm mất (thời gian)"], ["sacrifice", "hy sinh"]] },
    "Should employers allow staff to take short naps at work?": { a: "I think it's a sensible idea, as long as it's managed properly. Research suggests that a short nap can boost concentration and reduce mistakes, especially in the early afternoon when energy levels naturally dip. In Vietnam, lunchtime naps are already normal in many workplaces, and productivity doesn't seem to suffer. Of course, it wouldn't suit every job; a surgeon or a shop assistant can't just disappear for a nap, so it would have to depend on the role.", vocab: [["boost concentration", "tăng cường sự tập trung"], ["energy levels dip", "mức năng lượng giảm xuống"], ["productivity suffers", "năng suất bị ảnh hưởng"]] },
    "How does a lack of sleep affect students' performance?": { a: "The effects can be quite serious. Sleep is when the brain consolidates what we've learned during the day, so students who stay up cramming often remember less than those who go to bed at a reasonable time. Tired students also struggle to concentrate in class, become irritable and are more likely to make careless mistakes in exams. I've seen this myself: classmates who pulled all-nighters before exams often went blank on questions they had actually revised.", vocab: [["consolidate", "củng cố"], ["cramming", "học nhồi nhét"], ["pull an all-nighter", "thức trắng đêm (để học, làm việc)"]] },
    "Do you think people in the future will have more or less time to rest?": { a: "In theory, automation should free up more time, since machines and AI will take over many repetitive tasks. Some countries are already experimenting with a four-day working week. However, I'm a little sceptical, because in the past, every time technology made us more efficient, we simply filled the extra time with more work or more entertainment. So I suspect people will have more free hours on paper, but whether they actually use them to rest is another matter.", vocab: [["free up time", "giải phóng thời gian"], ["sceptical", "hoài nghi"], ["on paper", "trên lý thuyết, trên giấy tờ"]] },

    /* ===== Tiếng ồn ===== */
    "Is the area where you live noisy or quiet?": { a: "It's fairly noisy, to be honest. I live on a street with lots of small shops and street-food stalls, so there's constant chatter and the sound of motorbikes from early morning until late at night. I've got used to it over the years, though, and on the plus side, it never feels lonely or unsafe.", vocab: [["constant chatter", "tiếng trò chuyện không ngớt"], ["get used to", "trở nên quen với"], ["on the plus side", "về mặt tích cực"]] },
    "What kinds of noise annoy you the most?": { a: "Definitely construction noise, especially drilling. There's something about that high-pitched sound that goes right through me, and it's impossible to concentrate. I'm also irritated by people playing videos on their phones without headphones in public places, like on the bus. It just seems inconsiderate.", vocab: [["high-pitched", "the thé, cao vút"], ["go right through someone", "khiến ai cực kỳ khó chịu, buốt óc"], ["inconsiderate", "thiếu ý tứ, không nghĩ cho người khác"]] },
    "Do you prefer to study in silence or with some background sound?": { a: "I actually prefer a little background noise. Complete silence makes me restless, and I notice every tiny sound. So I often study in a café or put on instrumental music at a low volume. The only exception is when I'm doing something really demanding, like a practice exam, when I need total quiet.", vocab: [["restless", "bồn chồn, không yên"], ["at a low volume", "ở âm lượng nhỏ"], ["demanding", "đòi hỏi nhiều công sức"]] },
    "Have you ever complained about noise?": { a: "Only once. A neighbour was holding karaoke sessions until almost midnight several nights in a row, right before my exams. I didn't want to cause a scene, so I knocked on their door and politely explained the situation. They were quite apologetic, and they agreed to finish by ten, which was a reasonable compromise.", vocab: [["several nights in a row", "nhiều đêm liên tiếp"], ["cause a scene", "làm ầm ĩ, gây chuyện"], ["a reasonable compromise", "một sự thỏa hiệp hợp lý"]] },
    "Describe a place you have been to that was extremely noisy.": { a: "The noisiest place I've ever been to is a huge wholesale market in the centre of my city which I visited about a year ago.\n\nMy aunt runs a small clothes shop and buys stock there, and I tagged along to help her carry things. We arrived around five a.m., and even at that hour, the place was absolutely packed.\n\nThe noise came from several sources at once. Hundreds of traders were shouting prices at each other, porters were pushing heavy carts and yelling at people to get out of the way, and motorbikes loaded with bags were squeezing through narrow lanes, beeping their horns constantly. On top of that, some stalls had loudspeakers playing recorded advertisements on a loop. It was so loud that I had to repeat everything twice just to have a conversation with my aunt.\n\nMy feelings about it were quite mixed. At first, I found it overwhelming, and after about an hour I had a slight headache. But at the same time, it was fascinating to see how efficient everything was beneath the chaos; my aunt bargained like a professional. By the time we left, I had a new respect for people who work in that environment every day, although I was very relieved to get back to the relative quiet of the street outside.", vocab: [["tag along", "đi theo, đi cùng"], ["on a loop", "phát lặp đi lặp lại"], ["overwhelming", "choáng ngợp"]] },
    "Why are cities becoming noisier?": { a: "The main driver is growth. As urban populations increase, there are more vehicles on the roads, more construction projects and more businesses packed into the same space. Many cities are also becoming twenty-four-hour places, with deliveries, bars and entertainment running late into the night. In Vietnam specifically, the sheer number of motorbikes, combined with a habit of using horns frequently, adds a lot to the background noise. Unless planning improves, I think the problem will get worse.", vocab: [["the main driver", "động lực, nguyên nhân chính"], ["the sheer number of", "số lượng khổng lồ của"], ["background noise", "tiếng ồn nền"]] },
    "How does noise pollution affect people's health?": { a: "The effects are more serious than many people realise. In the short term, constant noise causes stress, headaches and difficulty concentrating. Over longer periods, it can disrupt sleep, and poor sleep is linked to problems like high blood pressure and heart disease. People exposed to very loud noise at work, such as factory or construction workers, can also suffer permanent hearing damage. There's also evidence that children who study near busy roads or airports perform worse at reading.", vocab: [["disrupt sleep", "làm gián đoạn giấc ngủ"], ["be exposed to", "tiếp xúc với"], ["permanent hearing damage", "tổn thương thính lực vĩnh viễn"]] },
    "What can governments do to reduce noise in residential areas?": { a: "There are several practical steps. First, they could enforce limits on when construction work is allowed, for example banning it at night and early in the morning. Second, city planners can keep residential zones away from highways and industrial areas, or build sound barriers and plant trees along busy roads. Fines for excessive horn use and loud karaoke late at night would also help. Finally, investing in electric buses and motorbikes would gradually make streets quieter.", vocab: [["enforce limits", "thực thi các giới hạn"], ["sound barrier", "tường cách âm, rào chắn tiếng ồn"], ["excessive", "quá mức"]] },
    "Are young people more tolerant of noise than older people?": { a: "Generally, I think they are. Young people tend to enjoy lively environments like concerts, clubs and crowded cafés, and many of them are used to having music in their ears all day. Older people, on the other hand, often value peace and quiet more, partly because they may sleep more lightly. That said, it's more about lifestyle than age; I know some teenagers who hate crowds and some grandparents who love a noisy family gathering.", vocab: [["tolerant of", "chịu đựng được, khoan dung với"], ["peace and quiet", "sự yên bình, tĩnh lặng"], ["sleep lightly", "ngủ không sâu, dễ tỉnh giấc"]] },

    /* ===== Đúng giờ & Quản lý thời gian ===== */
    "Are you usually on time for appointments?": { a: "Yes, I'd say I'm quite reliable. I usually aim to arrive about ten minutes early, because traffic in my city is so unpredictable. I'd much rather wait around for a bit than rush in flustered and apologising. The one exception is meeting close friends, where I'm a little more relaxed.", vocab: [["unpredictable", "khó đoán trước"], ["flustered", "bối rối, cuống quýt"], ["reliable", "đáng tin cậy"]] },
    "How do you feel when other people are late?": { a: "It depends on how late and whether they let me know. If someone sends a quick message saying they're running ten minutes behind, I don't mind at all. But if they turn up half an hour late without any warning, I do get annoyed, because it feels like they don't value my time.", vocab: [["run behind", "bị trễ so với kế hoạch"], ["turn up", "xuất hiện, đến nơi"], ["value someone's time", "tôn trọng thời gian của ai"]] },
    "Do you use a planner or an app to organise your day?": { a: "I use a calendar app on my phone for appointments and deadlines, since it sends reminders automatically. But for daily tasks, I still prefer a simple paper to-do list. There's something satisfying about physically crossing things off, and it helps me prioritise what really needs doing.", vocab: [["to-do list", "danh sách việc cần làm"], ["cross something off", "gạch bỏ (việc đã làm xong)"], ["prioritise", "ưu tiên"]] },
    "What time of day are you most productive?": { a: "I'm definitely a morning person. Between about seven and eleven, my mind is clear, so that's when I try to tackle the hardest tasks, like writing essays. By mid-afternoon, my energy drops, so I save easier jobs such as replying to emails for later in the day.", vocab: [["a morning person", "người hoạt động hiệu quả vào buổi sáng"], ["tackle", "giải quyết, xử lý"], ["energy drops", "năng lượng giảm sút"]] },
    "Describe a time when you were late for something important.": { a: "I'd like to talk about the morning I was late for a job interview, which was about a year and a half ago.\n\nIt was for an internship at a marketing agency, scheduled for nine o'clock. I'd prepared thoroughly the night before, but I made one big mistake: I didn't check the route properly.\n\nI left home at eight, thinking that would be plenty of time. Unfortunately, there was a burst water pipe on the main road, and the whole area was gridlocked. To make matters worse, when I finally got close, I discovered the office was in a different building from the one I'd assumed, so I wasted another ten minutes wandering around. I eventually arrived twenty minutes late, sweaty and out of breath.\n\nAs a result, the interview got off to a terrible start. The manager had to cut the session short, so I never got to talk about my best projects. Not surprisingly, I didn't get the internship.\n\nI learned a couple of valuable lessons from this. First, always plan for things going wrong, especially in a city with unpredictable traffic. Now I check the exact address and leave with at least thirty minutes to spare. Second, I realised that if I'm going to be late, I should phone ahead immediately rather than hoping I'll make it.", vocab: [["gridlocked", "tắc nghẽn hoàn toàn"], ["get off to a terrible start", "khởi đầu cực kỳ tệ"], ["with time to spare", "dư dả thời gian"]] },
    "Is being punctual equally important in all cultures?": { a: "Not really. Attitudes to time vary a lot between cultures. In countries like Germany or Japan, arriving even five minutes late to a meeting can be seen as disrespectful, and trains are expected to run to the minute. In many other places, including parts of Southeast Asia, people are more flexible, especially at social events, where arriving a little late is completely normal. In international business, though, punctuality is generally expected everywhere, so it's safest to be on time.", vocab: [["attitudes to time", "quan niệm về thời gian"], ["run to the minute", "chạy đúng từng phút"], ["disrespectful", "thiếu tôn trọng"]] },
    "Why do some people always seem to run out of time?": { a: "Often, it's because they underestimate how long tasks take. Someone might think a report will take an hour when it really needs three, so they're always playing catch-up. Procrastination is another big factor; people put off difficult tasks and then panic close to the deadline. Some also find it hard to say no, so they take on far more than they can realistically handle. In my experience, the people who manage time well aren't less busy; they're just better at prioritising.", vocab: [["play catch-up", "chạy theo để bắt kịp"], ["procrastination", "sự trì hoãn"], ["take on", "nhận làm, gánh vác"]] },
    "Should children be taught time-management skills at school?": { a: "I think so, yes. Many students only learn to manage their time at university, often the hard way, after missing deadlines. If schools taught simple techniques, like breaking large projects into smaller steps or using a weekly planner, children would build good habits early. These skills are also essential in almost every job. That said, it shouldn't become another subject with exams; it works better when it's built into ordinary homework and projects.", vocab: [["the hard way", "bằng cách trả giá, qua thất bại"], ["break something into smaller steps", "chia nhỏ việc gì thành các bước"], ["build good habits", "xây dựng thói quen tốt"]] },
    "Has modern technology helped us manage our time better, or has it made us busier?": { a: "I'd say it has done both. On the one hand, apps and online services save enormous amounts of time; we can bank, shop and book tickets in seconds, and calendar reminders mean fewer forgotten appointments. On the other hand, smartphones have blurred the line between work and personal life, so many people are expected to reply to messages at any hour. Social media also eats up hours without us noticing. So technology is a useful tool, but only if we control it.", vocab: [["blur the line between", "xóa nhòa ranh giới giữa"], ["at any hour", "vào bất kỳ giờ nào"], ["eat up", "ngốn, tiêu tốn"]] },

    /* ===== Hàng xóm & Láng giềng ===== */
    "Do you know the people who live next door to you?": { a: "Yes, quite well actually. On one side there's an elderly couple who have lived there for over thirty years, and on the other side a young family with two small kids. We're not best friends, but we always stop for a chat, and we keep an eye on each other's houses when someone's away.", vocab: [["stop for a chat", "dừng lại trò chuyện đôi câu"], ["keep an eye on", "để mắt, trông chừng"], ["be away", "đi vắng"]] },
    "How often do you talk to your neighbours?": { a: "Almost every day, but usually only briefly. I'll say hello when I leave for work, or we'll exchange a few words when we're taking out the rubbish. We have longer conversations during festivals like Tet, when people visit each other's homes, so those are the times I really catch up on local news.", vocab: [["exchange a few words", "trao đổi vài câu"], ["take out the rubbish", "đổ rác"], ["catch up on", "cập nhật (tin tức)"]] },
    "Have your neighbours ever helped you with anything?": { a: "Yes, several times. The most memorable was when our house flooded during a heavy storm a few years ago. Our neighbours came over with buckets and helped us move furniture upstairs before the water rose too high. Without them, we'd have lost a lot more, and I've never forgotten their kindness.", vocab: [["flood", "bị ngập lụt"], ["come over", "ghé sang"], ["the water rose", "nước dâng lên"]] },
    "What makes someone a good neighbour?": { a: "For me, a good neighbour is someone who's considerate and respects your privacy, but is also there when you need them. Basically, they keep the noise down, don't block your gate with their motorbike, and will happily lend you a ladder or take in a parcel. It's that balance between friendliness and not being nosy.", vocab: [["considerate", "chu đáo, biết nghĩ cho người khác"], ["take in a parcel", "nhận giúp bưu kiện"], ["nosy", "tọc mạch, hay xen vào chuyện người khác"]] },
    "Describe a neighbour who made a good impression on you.": { a: "I'd like to talk about Mrs Lan, who lived opposite my family when I was a teenager.\n\nShe was a widow in her sixties who ran a small grocery shop from her front room, and we lived across from her for about eight years.\n\nThere are a few things she did that I still remember clearly. Every afternoon, children from the street gathered outside her shop after school, and she would let us sit on little plastic stools and do our homework while our parents were still at work. She never charged us for the iced tea she handed out, and if anyone was struggling with maths, she would sit down and help. She also knew everyone's business, but in a caring way rather than a gossipy one: when my father was in hospital, she sent soup over every evening for a week without being asked.\n\nI think she was a good neighbour because she made our street feel like an extended family. In a city where many people barely know who lives next door, she created a sense of safety and belonging. Our parents could go to work knowing someone was keeping an eye on us, and we children grew up feeling that the whole street cared about us. When she eventually moved away to live with her son, the street honestly felt emptier.", vocab: [["an extended family", "đại gia đình"], ["a sense of belonging", "cảm giác thuộc về, gắn bó"], ["gossipy", "hay buôn chuyện, nói chuyện thiên hạ"]] },
    "Why do people in big cities often not know their neighbours?": { a: "A big reason is the way people live and work. Many city residents spend long hours at the office and commute, so they only come home to sleep. People also move house more often, especially renters, so there's little time to form relationships. On top of that, apartment buildings can be quite anonymous; you might share a lift with someone for years without exchanging names. And frankly, many people simply value their privacy and prefer to keep their social life separate from where they live.", vocab: [["move house", "chuyển nhà"], ["anonymous", "vô danh, không ai biết ai"], ["value their privacy", "coi trọng sự riêng tư"]] },
    "How can neighbours build a stronger sense of community?": { a: "Shared activities are probably the most effective way. For example, a residential building could organise a mid-autumn festival party for the children or a monthly clean-up of the common areas, which gives people a natural reason to talk. Online groups for each street or building also help, since neighbours can share news, sell second-hand items or ask for help. Even small gestures, like introducing yourself to new arrivals with a plate of fruit, can gradually create a warmer atmosphere.", vocab: [["common areas", "khu vực sinh hoạt chung"], ["second-hand items", "đồ cũ, đồ đã qua sử dụng"], ["small gestures", "những cử chỉ nhỏ"]] },
    "What kinds of problems commonly arise between neighbours?": { a: "Noise is probably the most common source of conflict, whether it's late-night karaoke, barking dogs or renovation work. Parking is another big one, particularly in narrow city streets where people block each other's entrances. Disputes can also arise over shared spaces, like who should pay to fix a leaking wall between two houses. Most of these issues could be resolved with a polite conversation, but when people avoid talking directly, small annoyances can build up into serious resentment.", vocab: [["a source of conflict", "nguồn gốc của xung đột"], ["dispute", "tranh chấp"], ["build up into", "tích tụ dần thành"]] },
    "Is it important for children to grow up surrounded by a close-knit community?": { a: "I believe it's very beneficial. When children know the adults around them, they feel safer and more confident exploring their neighbourhood, and they learn social skills by interacting with people of different ages, not just their parents and classmates. A close community also acts as an informal safety net; neighbours notice if something seems wrong. Having said that, it isn't essential, as children can still thrive in cities through school, sports clubs and other activities.", vocab: [["close-knit community", "cộng đồng gắn bó khăng khít"], ["an informal safety net", "mạng lưới bảo vệ không chính thức"], ["thrive", "phát triển mạnh mẽ, khỏe mạnh"]] }
  });
})(typeof self !== 'undefined' ? self : this);
